Plenty_0.report:
Description: MWE-207: Unauthorized Transfer. The contract allows transferring tokens from an address different from the message sender without checking the approval of the address owner.
                Recommendation: Check the business logic about the transfer and add the approval check if necessary.
                Code:   function transferFromWithLock(
    address _from,
    address _to,
    bytes32 _reason,
    uint256 _amount,
    uint256 _time
  ) public returns (bool) {
    uint256 validUntil = block.timestamp.add(_time);

    require(isWhitelistAdmin(_from), "ERC1132: Not whitelisted");
    require(tokensLocked(_to, _reason) == 0, "ERC1132: Already locked");
    require(_amount != 0, "ERC1132: Zero Amount");

    if (locked[_to][_reason].amount == 0) lockReason[_to].push(_reason);

    transferFrom(_from, address(this), _amount);

    locked[_to][_reason] = LockToken(_amount, validUntil, false);
    _lockedAmount.add(_amount);

    emit Locked(_to, _reason, _amount, validUntil);
    return true;
  }

